//#region src/commands/release-pr-body.ts
const releasePrBody = {
	usage: "<releases.json> <workspace-list.json>",
	run: (argv) => {
		const [releasesPath, workspacePath] = argv;
		if (!releasesPath || !workspacePath) throw new Error("usage: release-pr-body <releases.json> <workspace-list.json>");
		process.stdout.write(renderReleasePrBody(parseAppliedReleases(readFileSync(releasesPath, "utf8")), parseWorkspacePackages(readFileSync(workspacePath, "utf8"))));
	}
};

