//#region src/commands/shared-workflows-release.ts
const manifestVersion = (packagePath) => {
	const manifest = JSON.parse(readFileSync(packagePath, "utf8"));
	if (typeof manifest !== "object" || manifest === null || !("version" in manifest)) throw new Error(`${packagePath} has no version field`);
	const { version } = manifest;
	if (typeof version !== "string") throw new Error(`${packagePath}: expected a string version, got ${JSON.stringify(version)}`);
	return version;
};
const sharedWorkflowsRelease = {
	usage: "<package.json> <workflows-dir>",
	run: async (argv) => {
		const [packagePath, workflowsDir] = argv;
		if (!packagePath || !workflowsDir) throw new Error("usage: shared-workflows-release <package.json> <workflows-dir>");
		await releaseSharedWorkflows({
			api: apiFromEnv(),
			sha: requireEnv("GITHUB_SHA"),
			version: manifestVersion(packagePath),
			packagePath: dirname(packagePath),
			workflows: readdirSync(workflowsDir).filter((file) => file.startsWith("shared-") && file.endsWith(".yml")).sort()
		});
	}
};

