//#region src/signed-commit.ts
const collectChanges = ({ git, read }) => {
	const records = git([
		"status",
		"--porcelain=v1",
		"-z",
		"--untracked-files=all"
	]).split("\0").filter(Boolean);
	const added = /* @__PURE__ */ new Set();
	const deleted = /* @__PURE__ */ new Set();
	for (let index = 0; index < records.length; index += 1) {
		const record = records[index] ?? "";
		const state = record.slice(0, 2);
		const path = record.slice(3);
		if (state.includes("R") || state.includes("C")) {
			const origin = records[index + 1];
			index += 1;
			if (state.includes("R") && origin) deleted.add(origin);
			added.add(path);
			continue;
		}
		if (state.includes("D")) {
			deleted.add(path);
			continue;
		}
		added.add(path);
	}
	const readFile = read ?? ((path) => readFileSync(path));
	return {
		additions: [...added].map((path) => ({
			path,
			contents: readFile(path).toString("base64")
		})),
		deletions: [...deleted].map((path) => ({ path }))
	};
};
const createSignedCommit = async ({ api, git, branch, message, changes }) => {
	if (changes.additions.length === 0 && changes.deletions.length === 0) throw new Error("nothing to commit");
	const baseOid = git(["rev-parse", "HEAD"]).trim();
	const ref = `refs/heads/${branch}`;
	if (!(await api.createRef(ref, baseOid)).ok) {
		const updated = await api.updateRef(ref, baseOid);
		if (!updated.ok) throw new Error(`failed to point ${branch} at ${baseOid}: ${JSON.stringify(updated.payload)}`);
	}
	return api.createCommitOnBranch(branch, baseOid, message, changes);
};

