//#region src/commands/signed-commit.ts
const signedCommit = {
	usage: "<branch> <message>",
	run: async (argv) => {
		const [branch, message] = argv;
		if (!branch || !message) throw new Error("usage: signed-commit <branch> <message>");
		const git = (args) => execFileSync("git", [...args], { encoding: "utf8" });
		const oid = await createSignedCommit({
			api: apiFromEnv(),
			git,
			branch,
			message,
			changes: collectChanges({ git })
		});
		console.log(`created signed commit ${oid}`);
	}
};

